-- Tanda 0: quitar notas internas de 48 explicaciones (revisión 2026-10). EJECUTADO en producción el 2026-10-15: actualizadas 48, historial +48.
BEGIN;
SET LOCAL mir.motivo = 'Tanda 0 2026-10: quitar nota de revisión interna';
CREATE TEMP TABLE t0 (id int, antes_md5 text, despues text) ON COMMIT DROP;
INSERT INTO t0 VALUES
(5, '4017c1040cfc04baa5164dfcc8405712', 'La respuesta correcta es A) Carcinoma de células escamosas cutáneo invasivo. La imagen muestra un nódulo solitario de color rosado-rojizo, con una costra queratósica/hiperqueratósica amarillo-parduzca en su superficie, sobre el cuero cabelludo calvo y crónicamente fotoexpuesto de una paciente anciana. Este aspecto —nódulo único de crecimiento rápido, friable (sangra con facilidad), con costra queratósica prominente— es característico del carcinoma de células escamosas invasivo, no del sarcoma de Kaposi, que típicamente se presenta como lesiones violáceas o púrpuras (no rosadas), a menudo múltiples, sin ese componente hiperqueratósico tan marcado.'),
(12, 'edd8909bacee5f5df6bcab8e10601c79', 'La respuesta correcta es B) Carcinoma de seno piriforme derecho con adenopatía metastásica. El carcinoma de hipofaringe (seno piriforme) es característicamente silente en sus fases iniciales y con frecuencia se presenta ya con adenopatía cervical metastásica avanzada (nivel II-III) como primer signo, tal como ocurre en este paciente: masa laterocervical dura de 4 cm adherida a planos profundos, con exploraciones de cavidad oral, orofaringe, fosas nasales y oído normales, lo que dirige la atención hacia estructuras solo visibles mediante laringoscopia (hipofaringe/laringe). El fumador de larga evolución y la odinofagia son coherentes con esta localización.'),
(18, 'ce278e19e3f8aa9d96cdcc445d9def7a', 'La respuesta correcta es A) Angina de Ludwig. En la TC cervicofacial con contraste se objetiva un edema/infiltración difusa de los tejidos blandos del suelo de la boca y región submaxilar, de distribución bilateral y sin una colección focal bien delimitada con captación periférica en anillo que sugiera un absceso circunscrito. Este patrón de celulitis difusa de los espacios submandibular, sublingual y submentoniano, sin colección purulenta organizada, es característico de la angina de Ludwig, habitualmente de origen odontogénico (coherente con el antecedente de "boca séptica" del paciente), con dolor y edema submaxilar progresivos y falta de respuesta al tratamiento antiinflamatorio/antibiótico ambulatorio.'),
(19, '367982e86c581e4ac8a584391cd240d0', 'La respuesta correcta es B) Linfoma primario del sistema nervioso central. La RM cerebral muestra una masa periventricular izquierda relativamente bien delimitada, de señal heterogénea, que produce un efecto de masa claro sobre el ventrículo lateral izquierdo (compresión/asimetría respecto al contralateral) — hallazgo característico del linfoma primario del SNC asociado a VIH avanzado (CD4 muy bajos, habitualmente asociado a virus de Epstein-Barr), que típicamente se localiza en regiones periventriculares y produce efecto de masa, a diferencia de la leucoencefalopatía multifocal progresiva (lesiones de sustancia blanca sin efecto de masa ni captación) o la encefalitis por CMV (patrón periventricular difuso sin masa focal como la mostrada).'),
(68, 'c16f3b4c1d9896d30fffb4cdc73b19f9', 'La respuesta correcta es C) Resonancia magnética nuclear con gadolinio. Para el estudio específico de posibles complicaciones supuradas INTRACRANEALES de una sinusitis (no solo su extensión ósea sinusal), la RM con contraste de gadolinio es la prueba más sensible, al detectar cerebritis incipiente, absceso intracraneal, empiema subdural/epidural y trombosis de senos venosos durales —las complicaciones intracraneales propiamente dichas—, mientras que la TC del macizo facial está orientada principalmente a valorar la extensión sinusal y la erosión ósea.'),
(71, '142c8172fc3aa487d80403b8db2420b2', 'La respuesta correcta es B) Se realiza mediante la combinación de datos analíticos y ecográficos. El cribado combinado del primer trimestre integra marcadores bioquímicos séricos (PAPP-A y fracción libre de β-hCG) con hallazgos ecográficos (translucencia nucal, entre otros), junto con la edad materna, para calcular el riesgo individual de aneuploidía. La fracción libre de β-hCG está elevada, no disminuida, en la trisomía 21 (descarta A); el cribado se ofrece de forma universal a toda gestante en el primer trimestre, no restringido a población de riesgo (descarta C); y la translucencia nucal se mide con el feto en ligera extensión cervical, no en hiperflexión (descarta D).'),
(72, '3df778c4409fd100f8e6690a4d8edfa6', 'La respuesta correcta es B) Medida del diámetro biparietal fetal — esta NO es un criterio de selección para la vía del parto en presentación de nalgas. Los criterios clásicos de selección (peso fetal estimado, actitud de la cabeza fetal, tipo de presentación podálica —siendo la variedad footling/incompleta una contraindicación relativa por riesgo de prolapso de cordón— y características pélvicas maternas) determinan la elección de la vía del parto, pero el diámetro biparietal aislado no forma parte de estos criterios de selección estándar.'),
(73, '3efc917f1053bbb4b75362a35372ca1b', 'La respuesta correcta es A) El endometrio está engrosado y ante la clínica de la paciente, toma una biopsia endometrial con cánula de Cornier. En una mujer posmenopáusica con sangrado vaginal, el umbral de normalidad del grosor endometrial más ampliamente aceptado se sitúa en 4-5 mm; un endometrio de 7 mm se considera, por tanto, engrosado, y junto con la clínica de sangrado posmenopáusico está indicada la toma de biopsia endometrial (por ejemplo, mediante cánula de Cornier) para descartar patología maligna.'),
(147, '904b1f1a53be606473763feb7f229742', 'La respuesta correcta es D) Buena diferenciación ecográfica de corteza y médula renales — este es el dato que NO orienta a enfermedad renal crónica. Una buena diferenciación corticomedular en la ecografía refleja una arquitectura renal preservada, hallazgo típico de la afectación renal aguda, no crónica; de hecho, la pérdida de esta diferenciación es uno de los marcadores ecográficos clásicos de cronicidad. En cambio, los riñones de pequeño tamaño (A) y los antecedentes familiares de nefropatía (B) sí son datos que orientan a cronicidad, y los niveles elevados de fósforo (C) también se asocian con más frecuencia a la reducción sostenida y prolongada del filtrado glomerular propia de la enfermedad renal crónica establecida.'),
(173, '5ede49fe1618e64e1636e6e9b3204273', 'La respuesta correcta es D) Lesiones cutáneas en distintas fases evolutivas — esta es la afirmación que NO indica especial gravedad. Dentro de un mismo dermatoma, es habitual que las lesiones de herpes zóster no aparezcan todas de forma perfectamente sincrónica, por lo que encontrar vesículas, pústulas y costras conviviendo en distintas fases evolutivas dentro del brote no constituye por sí mismo un signo de alarma. En cambio, sí indican especial gravedad: la afectación multimetamérica (opción B, sugiere diseminación e inmunosupresión subyacente), la afectación del ala nasal (opción C, signo de Hutchinson, marcador de riesgo de afectación oftálmica grave por el nervio nasociliar), y la presencia de vesículas en el conducto auditivo externo (opción A, síndrome de Ramsay Hunt/zóster ótico, con riesgo de parálisis facial e hipoacusia).'),
(174, '5a0affa7cd890df4943c3b2fb7ef6842', 'La respuesta correcta es A) Isoniacida, durante nueve meses. Aunque el régimen de isoniacida y rifapentina semanal durante 3 meses (3HP) es en general el preferido por su mayor tasa de finalización, este paciente está en tratamiento con acenocumarol: la rifapentina, como la rifampicina, es un potente inductor enzimático que reduce significativamente la eficacia de los anticoagulantes orales antagonistas de la vitamina K, complicando su manejo. En un paciente anticoagulado, la isoniacida en monoterapia durante 9 meses evita esta interacción relevante y es la opción más adecuada.'),
(178, 'dc94aa3b0101ace8237b7a22d903aed2', 'La respuesta correcta es B) Test de Coombs. Ante una anemia macrocítica de instauración progresiva en una paciente con LES, el mecanismo más probable es la anemia hemolítica autoinmune, complicación bien reconocida de esta enfermedad. El test de Coombs directo es la determinación más directamente accionable, ya que confirma específicamente el mecanismo AUTOINMUNE de la hemólisis (detectando anticuerpos o complemento fijados a la superficie del hematíe), orientando de forma inequívoca hacia la intensificación del tratamiento inmunosupresor. La haptoglobina (A) confirma la existencia de hemólisis de forma inespecífica, sin identificar su mecanismo autoinmune, por lo que es un dato de apoyo pero menos directamente útil para decidir la actuación terapéutica que el propio Test de Coombs.'),
(192, '78adb6f847581e8cdf8ce77411b754f3', 'La respuesta correcta es D) Uno de los factores de riesgo más importantes es el tabaco. La imagen muestra un cáncer de cérvix avanzado. El tabaquismo es un cofactor de riesgo bien establecido e independiente para el cáncer de cérvix, incrementando el riesgo de persistencia de la infección por VPH y de progresión a carcinoma invasor, y se cita clásicamente entre los factores de riesgo más relevantes tras la propia infección por VPH.'),
(212, 'cb0b2257a080eaf92c62c694140200c3', 'La respuesta correcta es C) Durante la espiración normal, la presión alveolar disminuye con respecto al valor de la presión atmosférica —esta es la afirmación INCORRECTA que pedía identificar el enunciado—. Durante la espiración normal ocurre justo lo contrario: la presión alveolar AUMENTA por encima de la presión atmosférica (típicamente unos +1 cmH2O), siendo precisamente ese gradiente de presión positivo el que impulsa la salida de aire del pulmón; el aire fluye de mayor a menor presión, por lo que para que salga en espiración la presión alveolar debe superar a la atmosférica, no ser menor que ella. Este es un hecho de mecánica respiratoria básica.

La opción A sí es correcta: el bombeo linfático continuo que aspira el exceso de líquido del espacio pleural es, según describe Guyton en su Tratado de Fisiología Médica, un mecanismo que contribuye a mantener la ligera presión negativa entre las hojas pleurales, de forma complementaria (no sustitutiva) a la retracción elástica del pulmón y la caja torácica. Las opciones B y D también son correctas: la presión pleural se hace más negativa durante la inspiración, y la presión transpulmonar tiende a colapsar el pulmón a lo largo de todo el ciclo respiratorio, siendo contrarrestada por la presión pleural negativa.'),
(214, '485dc5cae052b3472e0e143d052998bd', 'La respuesta correcta es C) Alrededor del 50 % de la osmolaridad en el líquido intracelular se debe a los iones calcio — esta es la afirmación INCORRECTA que pedía el enunciado. El ion dominante de la osmolaridad intracelular es el potasio (junto con proteínas y fosfatos orgánicos), no el calcio: la concentración de calcio libre intracelular es extremadamente baja (del orden de 100 nM), por lo que su contribución a la osmolaridad del líquido intracelular es prácticamente despreciable, muy lejos del 50 % que afirma esta opción. Las opciones A, B y D sí son correctas: la distribución hídrica entre compartimentos depende de los solutos no difusibles; el sodio y el cloro son efectivamente los iones dominantes de la osmolaridad extracelular (aunque su porcentaje exacto pueda matizarse); y pequeños cambios en la concentración de solutos extracelulares generan grandes desplazamientos de agua entre compartimentos.'),
(231, '91a086e1eaa390354a631b032b922520', 'La respuesta correcta es B) El estimador de interés (como el riesgo relativo) de cada estudio. En un forest plot, el cuadrado que aparece junto a cada estudio representa el estimador puntual de efecto (por ejemplo, el riesgo relativo o el odds ratio) obtenido en ese estudio individual. El TAMAÑO de ese cuadrado es proporcional al peso que el estudio tendrá en el metaanálisis (típicamente determinado por el inverso de la varianza), y la línea horizontal que lo atraviesa representa su intervalo de confianza — pero lo que el cuadrado en sí simboliza es el estimador puntual, no el peso.'),
(239, 'c8499ef5cbfc2a3376a1b9d0eff17808', 'La respuesta es naproxeno porque es el AINE con el perfil de riesgo cardiovascular más favorable en pacientes con antecedentes de cardiopatía isquémica, según la evidencia actual y las recomendaciones de seguridad cardiovascular. Aunque todos los AINEs tradicionales aumentan el riesgo cardiovascular, el naproxeno ha mostrado en estudios epidemiológicos un incremento menor del riesgo de eventos cardiovasculares comparado con otros AINEs como ibuprofeno o ketorolaco. El celecoxib, a pesar de ser un inhibidor selectivo de COX-2, no ofrece ventajas claras de seguridad cardiovascular respecto al naproxeno y también requiere precauciones en este contexto de cardiopatía isquémica previa.

Esta recomendación refleja el consenso actual en guías de seguridad cardiovascular, aunque el margen de seguridad entre naproxeno y otras opciones es relativo; en todo caso, en un paciente con alto riesgo cardiovascular debería evaluarse primero si es posible evitar el AINE o usar inhibidores de bomba de protones como gastroprotección de base.'),
(258, '6918384bd472d9d5c3b400a37a029a85', 'La respuesta correcta es D) Inducción del parto a partir de las 37 semanas de gestación. Ante una restricción de crecimiento intrauterino (percentil 6) con Doppler de arteria umbilical alterado (índice de pulsatilidad > percentil 95) a las 36,5 semanas, sin signos de preeclampsia materna, el manejo estándar basado en la evidencia actual es la finalización programada de la gestación en torno a las 37 semanas, una vez alcanzado un punto en el que el beneficio de la madurez fetal supera el riesgo de continuar el embarazo con compromiso placentario documentado, en lugar de prolongar la vigilancia hasta las 40 semanas.'),
(259, '34d05001101aa614e82f8c76fb947bc7', 'La respuesta correcta es B) Insuficiencia ovárica prematura. Inicia estudio con cariotipo e indica terapia hormonal sustitutiva. Ante una insuficiencia ovárica prematura confirmada (FSH elevada, estradiol bajo, amenorrea, confirmación a los 2 meses), el estudio con cariotipo está indicado en mujeres jóvenes para descartar causas genéticas (como mosaicismo de Turner), y la terapia hormonal sustitutiva se considera un tratamiento esencialmente de primera línea (no diferido a segunda línea) según las guías de referencia (ESHRE), recomendada para todas las mujeres con IOP sin contraindicaciones específicas, dado el beneficio en la prevención de las consecuencias a largo plazo del déficit estrogénico (óseas, cardiovasculares) además del control sintomático.'),
(336, '13d780355649a51c42bd733326c1a5c3', 'La respuesta correcta es B) Existe una jerarquía progresiva obligada tanto para la adquisición como para la pérdida de las actividades de la vida diaria (AVD), desde las instrumentales hasta las avanzadas — esta es la afirmación INCORRECTA que pedía el enunciado. La jerarquía clásica de pérdida/adquisición de actividades de la vida diaria (jerarquía de Katz) es específicamente sobre las actividades BÁSICAS (baño, vestido, aseo, transferencias, continencia, alimentación), no sobre una progresión desde las instrumentales hasta las avanzadas; además, calificar esta jerarquía como "obligada" es una sobregeneralización, ya que el patrón de pérdida funcional puede variar según la etiología subyacente. Las demás opciones son correctas: la valoración funcional es efectivamente una medida global del impacto de los problemas de salud (A), debe emplearse el estado funcional previo al ingreso para establecer objetivos realistas en el paciente hospitalizado (C), y en la práctica habitual la función se mide mayoritariamente con informes autorreferidos o de terceros, reservando la evaluación estructurada para ocasiones específicas (D).'),
(344, '1f63dea70855cd0f170f0ed0e661a0f7', 'La respuesta correcta es A) El control glucémico intensivo en el periodo perioperatorio por lo común se acompaña de mejoría en los resultados — esta es la afirmación INCORRECTA que pedía el enunciado. La evidencia de ensayos clínicos de referencia (como NICE-SUGAR) demostró que el control glucémico intensivo en el perioperatorio y en el paciente crítico NO se asocia de forma consistente a mejores resultados, y puede incluso aumentar la mortalidad por el riesgo de hipoglucemia iatrogénica, motivo por el cual las guías actuales recomiendan objetivos más moderados. Las demás opciones son correctas: el rango de 100-180 mg/dL es un objetivo perioperatorio razonable (B), la optimización preoperatoria está indicada si la HbA1c es >9% (C), y el buen control glucémico perioperatorio sí reduce las infecciones y, en el paciente crítico, puede reducir la mortalidad (D).'),
(353, 'a69172662b9b0cab33bdb492f967c301', 'La respuesta correcta es C) Función renal y presión arterial. En la esclerodermia difusa de reciente diagnóstico, el riesgo más crítico durante los primeros meses de evolución es la crisis renal esclerodérmica, una complicación aguda, potencialmente fatal y que ocurre característicamente en los primeros 1-4 años de la enfermedad (con mayor riesgo en las fases iniciales de la forma difusa). Por ello, la monitorización estrecha de la función renal y de la presión arterial es la prioridad de seguimiento en este periodo, permitiendo la detección precoz e instauración inmediata de IECA ante la primera sospecha. Las pruebas funcionales respiratorias y la TC de tórax (D) son igualmente relevantes para la enfermedad pulmonar intersticial, pero esta suele desarrollarse de forma algo más progresiva, mientras que la crisis renal es la emergencia más característica de esta fase inicial.'),
(354, 'ab4504f9e2940cdab5a10253c6b8171f', 'La respuesta correcta es B) Fiebre mediterránea familiar. El origen geográfico mediterráneo del paciente (España), el inicio en la infancia, los episodios autolimitados de fiebre con dolor abdominal y defensa a la palpación (peritonitis subclínica recurrente, que en este caso motivó una apendicectomía innecesaria sin hallazgos inflamatorios, un antecedente clásicamente asociado a la FMF por la peritonitis recurrente que simula abdomen agudo), la corta duración de los episodios (2-3 días) y las lesiones erisipeloides en la cara anterolateral de las piernas (el "eritema erisipeloide", hallazgo cutáneo específicamente descrito como criterio diagnóstico clásico de la FMF, no exclusivo de TRAPS) configuran conjuntamente el cuadro característico de la fiebre mediterránea familiar. El síndrome periódico asociado al receptor del TNF (TRAPS) cursa característicamente con episodios más prolongados (frecuentemente >7-10 días) y menor asociación con el origen mediterráneo específicamente.'),
(398, '5555c67b46c4513e4d2ced013df81812', 'La respuesta correcta es C) Infarto isquémico agudo en territorio de arteria cerebral posterior derecha. El paciente presenta un perfil de riesgo vascular completo (hipertensión arterial, dislipemia, infarto agudo de miocardio previo) y una hemianopsia homónima izquierda de instauración relativamente aguda, signo de localización clásico de infarto en el territorio de la arteria cerebral posterior derecha, que irriga la corteza occipital y, por tanto, la vía óptica retroquiasmática de ese lado. La amnesia y el deterioro cognitivo rápidamente progresivo se explican por la afectación concomitante de estructuras témporo-mesiales e hipocampales, territorio también dependiente de la arteria cerebral posterior. No hay en el enunciado ningún dato que respalde un absceso cerebral secundario a otitis media (opción A): no se menciona fiebre, otalgia, otorrea, leucocitosis ni ningún antecedente ótico, y el mecanismo causal de la otitis solo podría asumirse de forma implícita, no derivarse del caso clínico. Tampoco hay datos de trombosis venosa (opción B, que cursaría con clínica de hipertensión intracraneal y hallazgos de trombosis en los senos venosos) ni de una neoplasia glial con edema perilesional (opción D, cuya presentación sería subaguda-crónica y no explicaría por sí sola el inicio con hemianopsia homónima aguda en un paciente con perfil vascular de alto riesgo).'),
(417, '74b2e41b97829a0f9db71c03d65be200', 'La respuesta correcta es A) Los cambios de presión arterial se acompañan de cambios proporcionales en la filtración glomerular — esta es la afirmación INCORRECTA que pedía el enunciado. El riñón dispone de mecanismos de autorregulación (miogénico y retroalimentación tubuloglomerular) que mantienen el flujo sanguíneo renal y el filtrado glomerular relativamente constantes ante cambios de presión arterial dentro de un rango fisiológico amplio (aproximadamente 80-180 mmHg), por lo que los cambios de FG NO son proporcionales a los cambios de presión arterial, sino que se amortiguan. Las demás opciones son correctas: se produce vasoconstricción de las arteriolas eferentes mediada por angiotensina II para mantener la presión de filtración (B); aumenta la actividad de los núcleos supraóptico y paraventricular, productores de ADH, en respuesta a la hipovolemia/hiperosmolalidad (C); y aumenta la secreción renal de potasio secundaria al hiperaldosteronismo activado (D).'),
(445, '1bc394fccd0b1447a471b7a88df83651', 'La respuesta correcta es A) Colgajo anterolateral fasciocutáneo de muslo, pediculado. Un colgajo pediculado depende de su pedículo vascular nativo y tiene un arco de rotación limitado por la distancia anatómica entre el origen vascular y el defecto a cubrir. El colgajo anterolateral de muslo (ALT) pediculado, con origen en la arteria circunfleja femoral lateral a nivel del muslo, no tiene alcance anatómico suficiente para cubrir un defecto en la región cervical posterior de forma pediculada, por la distancia entre el muslo y el cuello. En cambio, el colgajo libre SCIP (D), aunque de escaso volumen y predominantemente adipofascial, sí podría transferirse microquirúrgicamente a cualquier localización, incluida la región cervical, como colgajo libre; y tanto el dorsal ancho libre (B) como el trapecio pediculado (C) sí alcanzan o pueden diseñarse para alcanzar la región cervical posterior.'),
(458, '134d8b8b09bee06ba0a6f2497949fa14', 'La respuesta correcta es B) Antibioticoterapia oral, junto con el vaciado adecuado de la mama. Ante una mastitis puerperal con afectación sistémica (malestar general, fiebre), el tratamiento estándar actual combina antibioticoterapia oral dirigida a Staphylococcus aureus con el vaciado frecuente y completo de la mama (continuando la lactancia o extracción), medida fundamental para resolver la obstrucción y prevenir la progresión a absceso. Los antibióticos tópicos y los lavados con antisépticos no constituyen una pauta de tratamiento estándar reconocida para la mastitis puerperal.'),
(498, '0cfdfa990e444c69fba9529b09cf0817', 'La respuesta correcta es D) La manifestación hematológica más frecuente es la leucopenia — esta es la afirmación INCORRECTA que pedía el enunciado. La manifestación hematológica más frecuente en la artritis reumatoide es la ANEMIA (típicamente de trastorno crónico), presente hasta en el 30-70% de los pacientes, no la leucopenia, que es mucho menos frecuente y se asocia principalmente al síndrome de Felty (una variante infrecuente de AR de larga evolución). Las demás opciones son correctas: la artritis reumatoide es efectivamente la causa más frecuente de síndrome de Sjögren secundario (A), la pericarditis es la manifestación cardiaca más habitual (B), y la pleuritis reumatoide cursa característicamente con un exudado de glucosa muy baja (C).'),
(519, '7682fa06455232a397e572e5a9ad08df', 'La respuesta correcta es D) Tumoración maligna obstructiva de colédoco distal. Solicitar una TC abdominal para estudio de extensión local y a distancia. La combinación de ictericia progresiva indolora, pérdida de peso de un mes de evolución y, sobre todo, una vesícula biliar palpable/distendida en el contexto de dilatación de la vía biliar (signo de Courvoisier: vesícula distendida y no dolorosa en presencia de ictericia obstructiva) es altamente sugestiva de obstrucción maligna del colédoco distal (típicamente neoplasia de cabeza de páncreas o colangiocarcinoma distal), no de coledocolitiasis. Cuando la obstrucción biliar es de origen litiásico crónico, la vesícula suele estar fibrosada por colecistitis previa y no logra distenderse pese a la obstrucción, a diferencia de lo que ocurre en la obstrucción maligna progresiva. El antecedente de amoxicilina/clavulánico es un dato distractor que podría sugerir toxicidad farmacológica (A), pero no explica la dilatación mecánica de la vía biliar ni el signo de Courvoisier.'),
(554, '705a7140a6ab3ce6d6970248db8f197d', 'La respuesta correcta es B) Deben tratarse los síntomas con analgésicos además del tratamiento del herpes. El herpes zóster cursa con frecuencia con dolor significativo (neuralgia aguda), por lo que el manejo analgésico complementario es una recomendación básica y no controvertida, independientemente de si se pauta o no tratamiento antiviral. La opción D es incorrecta porque el tratamiento antiviral oral no está indicado "solo" en pacientes inmunodeprimidos: las guías actuales también lo recomiendan en mayores de 50 años, dolor moderado-grave, afectación no troncular (cara, extremidades) y afectación oftálmica u ótica, entre otros criterios — restringirlo exclusivamente a la inmunosupresión es una afirmación demasiado estrecha para ser cierta.'),
(555, 'fb3dc876a70cc607c5ed892cc470c5c9', 'La respuesta correcta es C) La medida del efecto terapéutico del tratamiento es a través de la desaparición del picor en las primeras 48 horas — esta es la afirmación INCORRECTA que pedía el enunciado. El prurito de la escabiosis es una reacción de hipersensibilidad frente al ácaro y sus productos, y característicamente PERSISTE durante 2-4 semanas tras un tratamiento eficaz, incluso habiendo eliminado por completo el parásito; por ello, la persistencia del picor en las primeras 48 horas NO indica fracaso terapéutico, y valorar la eficacia del tratamiento por la desaparición inmediata del prurito es un criterio clínico erróneo. Las demás opciones son correctas: la aplicación de permetrina al 5% desde el cuello (línea mandibular) hasta los pies durante 8-14 horas es el tratamiento de elección (A), el lavado de la ropa a 50°C o alternativas equivalentes elimina el parásito (B), y la ivermectina oral en dosis única es el tratamiento de elección en fracaso terapéutico o sarna nodular (D).'),
(556, '8d8df2d31e5ae95163c05bafa02c8a2d', 'La respuesta correcta es A) Anfotericina B liposomal. La anfotericina B liposomal en monoterapia (a dosis y duración ajustadas) es el tratamiento de primera línea recomendado para la leishmaniasis visceral en personas con VIH e inmunodeficiencia grave. El voriconazol (opción B) es un antifúngico sin actividad frente a Leishmania y no tiene ningún papel en su tratamiento.'),
(578, '71dcb283632e244f151ef7067db3c24e', 'La respuesta correcta es B) La detección y el tratamiento de la dependencia del tabaco se considera una intervención con coste-efectividad favorable, sin repercusión en términos de coste por año de vida ganado — esta es la afirmación INCORRECTA que pedía el enunciado. La afirmación es internamente contradictoria: la coste-efectividad de una intervención sanitaria se mide precisamente en términos de coste por año de vida ajustado por calidad/año de vida ganado, por lo que decir que es coste-efectiva "sin repercusión" en ese indicador no tiene sentido; de hecho, el tratamiento del tabaquismo es una de las intervenciones sanitarias con mejor relación coste-efectividad documentada. La atención primaria sí es ampliamente reconocida como el entorno más favorable para el abordaje del tabaquismo por su accesibilidad y capacidad de contacto repetido con la población (A); la combinación de estrategias farmacológicas y no farmacológicas es la más efectiva (C); y los fumadores sin intención de dejarlo con frecuencia presentan déficit informativo o desmotivación tras recaídas previas (D).'),
(582, 'f7c4ffb10b9792a499c675df570879b6', 'La respuesta correcta es B) Síndrome de lisis tumoral. La combinación de fracaso renal agudo, hiperuricemia, hiperpotasemia, hiperfosfatemia e hipocalcemia tras una sesión de quimioterapia reciente en un paciente con una neoplasia hematológica de alta carga tumoral (leucemia linfoblástica aguda) es la presentación bioquímica característica y definitoria del síndrome de lisis tumoral, causado por la liberación masiva de contenido intracelular tras la destrucción de células tumorales. Ni la hiperemesis postquimioterapia (D) ni la hipocalcemia aislada por citostáticos (C) explican este patrón bioquímico completo, y no hay datos clínicos que sugieran sepsis (A).'),
(590, 'f6f3df493a84c63aad05b00274b6fb33', 'La respuesta correcta es D) Existen pacientes que cumplen los criterios clasificatorios de la enfermedad que presentan mutaciones con pérdida de función en el gen CECR1 que codifica la adenosina desaminasa 2. El cuadro clínico (astenia, pérdida de peso, artromialgias, mononeuritis múltiple, livedo reticularis, nódulos subcutáneos dolorosos, reactantes de fase aguda muy elevados) es característico de poliarteritis nodosa (PAN). Es un hecho cada vez más reconocido en la literatura reumatológica reciente que un subgrupo de pacientes que cumplen los criterios clasificatorios de PAN presentan mutaciones bialélicas con pérdida de función en el gen CECR1/ADA2, causantes de la deficiencia de adenosina desaminasa 2 (DADA2), una vasculitis genéticamente definida que puede fenocopiar la PAN clásica. La alteración electroneuromiográfica más característica de la PAN es precisamente la mononeuritis múltiple observada en este paciente (no la neuropatía de fibra fina, que es más propia de otras vasculitis o del Sjögren), por lo que la opción A es incorrecta.'),
(591, 'd986a45c3bcb13d1c88ed22227ab0479', 'La respuesta correcta es D) En casos de resistencia una opción es el tratamiento con itraconazol oral 200 mg cada 24 horas durante 12 semanas. Este es un régimen terapéutico real y reconocido como alternativa de segunda línea en onicomicosis resistente al tratamiento inicial: el itraconazol oral continuo a dosis de 200 mg/24h durante 12 semanas (además de la pauta en pulsos) es una opción válida documentada para onicomicosis del pie cuando fracasa la primera línea.'),
(617, '1c23f38f8a3afb514198715f15ea3309', 'La respuesta correcta es B) Hemoglobinuria paroxística a frigore. El hallazgo de un anticuerpo con especificidad anti-P es el dato diagnóstico clave: corresponde a la hemolisina bifásica de Donath-Landsteiner, el autoanticuerpo IgG específico frente al antígeno P eritrocitario que define la hemoglobinuria paroxística a frigore, un cuadro de hemólisis intravascular desencadenada por el frío (en este caso, el circuito extracorpóreo de diálisis), coherente con la anemia, el aumento de LDH y de hemoglobina libre en plasma. La crioglobulinemia (D) no se caracteriza por un anticuerpo con especificidad anti-P frente a antígenos eritrocitarios, sino por inmunoglobulinas que precipitan con el frío, por lo que no explica este hallazgo inmunohematológico específico.'),
(635, '3383ff3929f14add099df378137636eb', 'La respuesta correcta es D) Puede comer pescado previamente congelado a -20ºC durante 72 horas en el domicilio o pescado congelado industrial. Cocinar el pescado a 45°C (opción C) es una temperatura INSUFICIENTE para inactivar las larvas de Anisakis simplex: las guías de seguridad alimentaria exigen alcanzar al menos 60°C durante al menos 1 minuto en el núcleo del alimento para garantizar la muerte del parásito, por lo que 45°C no ofrece protección real frente a la reexposición antigénica en un paciente ya sensibilizado. La congelación a -20°C (ya sea doméstica durante al menos 72 horas o industrial) sí es un método de inactivación reconocido y recomendado por la normativa de seguridad alimentaria (RD 1420/2006) para el consumo de pescado crudo o poco cocinado en pacientes con alergia a Anisakis.'),
(647, '0e2837fb702f8be1a0852a2af6bd597c', 'La respuesta correcta es C) Cuando hay un tendón sin paratendón en la base de la herida. Un tendón expuesto sin su paratendón carece de un lecho vascularizado capaz de nutrir un injerto de piel parcial durante el periodo crítico de revascularización (los primeros 3-5 días), por lo que constituye una contraindicación real para este tipo de cobertura, siendo necesario recurrir a un colgajo o a otras técnicas de cobertura vascularizada. La infección activa del lecho (D) es también un escenario desfavorable para el injerto, pero suele considerarse una contraindicación relativa y transitoria (se puede tratar y diferir el injerto), mientras que la ausencia de paratendón es una limitación estructural del lecho receptor en sí mismo.'),
(665, '2d2c784d326f5675d6ffd7e3c6198011', 'La respuesta correcta es D) Cardiopatía congénita. La nariz en silla de montar SÍ es un estigma reconocido de la sífilis congénita tardía (por rinitis sifilítica en la infancia que destruye el cartílago nasal, con deformidad evidente en años posteriores), formando parte del conjunto clásico de estigmas óseos y faciales junto con los dientes de Hutchinson y la frente olímpica. En cambio, la sífilis congénita no produce típicamente cardiopatías estructurales congénitas: la afectación cardiovascular sifilítica (aortitis, insuficiencia aórtica) es propia de la sífilis terciaria ADQUIRIDA en el adulto, décadas después de la infección, no de la forma congénita. Por ello, la cardiopatía congénita es la manifestación que NO es habitual en la sífilis congénita tardía.'),
(719, '9742fbe1c1018eb3179e0467a7e0a846', 'La respuesta D es la correcta porque el cuadro clínico e imagenológico apunta fundamentalmente a una obstrucción biliar de causa maligna que requiere confirmación urgente.

El paciente presenta un síndrome de obstrucción biliar clásico (ictericia, prurito, síndrome tóxico) con dilatación de vía biliar intra y extrahepática y vesícula distendida, lo que indica obstrucción distal del colédoco. Aunque recibió amoxicilina-clavulánico (que causa colestasis), la duración de síntomas (un mes) y el patrón obstructivo con dilatación significativa hace improbable que sea únicamente colestasis medicamentosa, que típicamente no causa dilata­ción de vías biliares. La coledocolitiasis distal es menos probable en este contexto porque un cálculo no explicaría el síndrome tóxico (fiebre/malestar sistémico) ni el patrón de presentación progresiva en ancianos. El TC abdominal es el estudio de imagen de elección para caracterizar lesiones obstructivas malignas (cáncer de páncreas, colédoco o ampolla de Vater), que son las causas más frecuentes de obstrucción biliar en ancianos sin antecedente de litiasis biliar establecida, y permite estadificar y determinar resecabilidad.'),
(729, 'aa648410e8aed23f30863d33fccc9052', 'La respuesta correcta es C) Derivación de la vía urinaria de forma bilateral. La ecografía ya establece el diagnóstico y la causa de la obstrucción (dilatación pielocalicial y ureteral bilateral con litiasis en todos los grupos caliciales y en el uréter proximal izquierdo), por lo que, ante un paciente con anuria de 48 horas, insuficiencia renal aguda grave (creatinina 7 mg/dL, FG<15) e hiperpotasemia (K 5,7 mmol/L), la prioridad es la derivación urgente de la vía urinaria bilateral (mediante catéteres doble J o nefrostomías percutáneas) para revertir la obstrucción, no demorar el tratamiento solicitando pruebas de imagen adicionales que no cambiarían la actitud terapéutica inmediata. La analgesia y sueroterapia para forzar diuresis (A) o los diuréticos (B) son contraproducentes en una obstrucción bilateral establecida.'),
(742, '3dc2fd23193700dadb69a833093b5dab', 'La respuesta correcta es A) Paracetamol. Ante una gonalgia nocturna de intensidad leve-moderada como causa del insomnio de conciliación y mantenimiento en una paciente de 90 años sin tratamiento analgésico previo, el primer escalón terapéutico apropiado es tratar la causa subyacente del insomnio (el dolor) con el analgésico más seguro disponible en el anciano: el paracetamol, primer escalón de la escalera analgésica de la OMS y opción de primera línea en dolor musculoesquelético leve-moderado en geriatría. Resolver la causa del insomnio evita añadir un fármaco psicótropo/sedante innecesario en una paciente de edad muy avanzada, minimizando el riesgo de polifarmacia, caídas y efectos adversos, en línea con los criterios Beers de prescripción en el anciano. La mirtazapina, el diazepam y la trazodona serían opciones a considerar solo si el insomnio persistiera tras un control analgésico adecuado del dolor, no como primera opción cuando la causa es identificable y tratable de forma más segura y directa.'),
(753, 'fa6d6aac115fc185bbd178dc908c6cf3', 'La respuesta correcta es A) Si presenta más de tres episodios anuales está indicado realizar profilaxis con un antiviral como valaciclovir 500 mg cada 12 horas o 1 g al día, durante seis meses — esta es la afirmación INCORRECTA. El umbral y la pauta de profilaxis supresora en el herpes labial recurrente frecuente se establecen habitualmente con un número de episodios anuales superior al indicado aquí, por lo que la formulación de esta opción no se ajusta a la pauta estándar. Las demás opciones son correctas: en un cuadro leve de lesión única puede no tratarse o emplear medidas tópicas conservadoras (B), ante riesgo de afectación oftálmica está indicado el tratamiento antiviral oral a dosis más altas (C), y la fotoprotección es una medida preventiva reconocida frente a las recurrencias (D).'),
(754, '18c0ee6a13384f8a0b24b09142ac4878', 'La respuesta correcta es A) Es una enfermedad de declaración obligatoria. El carbunco (ántrax), incluida su forma cutánea, es una enfermedad de declaración obligatoria en España y en la mayoría de los países, dado su potencial de alerta en salud pública (incluida la posibilidad de exposición zoonótica o bioterrorista) — una afirmación simple, correcta y sin matices.'),
(757, 'c00252a30670b4118bc72927185ed267', 'La respuesta correcta es C) Debe iniciar tratamiento con benznidazol para modificar la evolución de la enfermedad — esta es la afirmación INCORRECTA que pedía el enunciado. En la enfermedad de Chagas crónica con cardiopatía ya establecida, el ensayo clínico de referencia BENEFIT (2015) no demostró que el tratamiento con benznidazol reduzca la progresión de la cardiopatía chagásica ni los eventos cardiológicos mayores, aunque sí reduce la parasitemia y la positividad serológica; por ello, no puede afirmarse sin matices que el benznidazol "modifique la evolución de la enfermedad" en este contexto de afectación cardíaca ya instaurada. Las demás opciones son correctas: la inmunofluorescencia es una prueba serológica válida para confirmar IgG frente a T. cruzi (A), la PCR tiene efectivamente un valor diagnóstico limitado en la fase crónica por la parasitemia baja e intermitente (B), y el estudio de familiares cercanos está indicado ante un caso confirmado por el riesgo de transmisión vertical y exposición compartida (D).'),
(764, 'abb45392954cab78a20e038ebee131df', 'La respuesta correcta es C) La mayoría de las recomendaciones sobre profilaxis antibiótica en cirugía cardíaca aconsejan mantener los antibióticos al menos 48 horas tras el procedimiento quirúrgico — esta es la afirmación INCORRECTA que pedía el enunciado. Las guías actuales de profilaxis antibiótica quirúrgica (incluidas las específicas de cirugía cardíaca) recomiendan limitar la duración de la profilaxis a un máximo de 24-48 horas, y la tendencia general es hacia duraciones más cortas (incluso dosis única o <24h en la mayoría de procedimientos), no a mantenerla sistemáticamente 48 horas como estándar mayoritario; prolongar la profilaxis más allá de lo necesario no reduce más las infecciones y favorece resistencias. Las demás opciones son correctas: la diabetes, malnutrición, obesidad e inmunosupresión sí son factores de riesgo del paciente (A); el control intensivo perioperatorio de la glucemia sí es una buena práctica de prevención (B); y la antibioterapia local (cemento con antibiótico) sí se emplea como profilaxis y, en menor medida, como coadyuvante terapéutico en la sustitución de prótesis articulares infectadas (D).'),
(787, '0520ed781dd5d1b18198ac60409c9d48', 'La respuesta correcta es A) Glomerulonefritis pauciinmune. La combinación de glomerulonefritis necrotizante con semilunas e inmunofluorescencia directa NEGATIVA es, por definición, el patrón "pauciinmune" (ausencia de depósitos inmunes significativos), típicamente asociado a vasculitis ANCA-positivas. El síndrome de Goodpasture (enfermedad por anticuerpos antimembrana basal glomerular) se caracteriza precisamente por lo contrario: un patrón de inmunofluorescencia directa POSITIVO, con depósitos LINEALES de IgG (y con frecuencia C3) a lo largo de la membrana basal glomerular, por lo que una inmunofluorescencia negativa descarta este patrón y apunta a la vasculitis pauciinmune. El dato de laboratorio de inmunología que ayudaría a confirmar el diagnóstico sería la determinación de ANCA (no de anticuerpos anti-MBG, que se esperarían negativos).');
DO $$ DECLARE n int; h0 int; h1 int; BEGIN
  SELECT count(*) INTO h0 FROM explicaciones_historial;
  UPDATE preguntas p SET explicacion = t0.despues FROM t0 WHERE p.id = t0.id AND md5(p.explicacion) = t0.antes_md5;
  GET DIAGNOSTICS n = ROW_COUNT;
  SELECT count(*) INTO h1 FROM explicaciones_historial;
  IF n <> 48 OR h1 - h0 <> 48 THEN RAISE EXCEPTION 'actualizadas %, historial +% (esperado 48)', n, h1 - h0; END IF;
  RAISE NOTICE 'actualizadas %, historial +%', n, h1 - h0;
END $$;
COMMIT;
